Clase Figura
    Publico Metodo Area() Como Real
        Retornar 0.0;
    FinMetodo
FinClase

Clase Cuadrado Hereda De Figura
    Privado Definir lado Como Entero;

    Metodo Constructor(unLado Como Entero)
        Este.lado <- unLado;
    FinMetodo

    Publico Metodo Area() Como Real
        Retornar Este.lado * Este.lado;
    FinMetodo
FinClase

Clase Circulo Hereda De Figura
    Privado Definir radio Como Entero;

    Metodo Constructor(unRadio Como Entero)
        Este.radio <- unRadio;
    FinMetodo

    Publico Metodo Area() Como Real
        Retornar Este.radio * Este.radio * 3.14;
    FinMetodo
FinClase

Clase TrianguloIsoceles Hereda De Figura
    Privado Definir base Como Entero;

    Metodo Constructor(unaBase Como Entero)
        Este.base <- unaBase;
    FinMetodo

    Publico Metodo Area() Como Real
        Retornar Este.base * Este.base / 2;
    FinMetodo
FinClase

Proceso CalcularAreaPolimorfica
    Definir tipo Como Entero;
    Definir medida Como Entero;
    Definir figura Como Figura;
    Leer tipo;
    Leer medida;
    Si tipo = 1 Entonces
        figura <- Nuevo Cuadrado(medida);
    SiNo
        Si tipo = 2 Entonces
            figura <- Nuevo Circulo(medida);
        SiNo
            figura <- Nuevo TrianguloIsoceles(medida);
        FinSi
    FinSi
    Escribir figura.Area();
FinProceso
